    fn split_column_value(&self, v: &Value, separator: &Regex) -> Vec<Value> {
        if let Ok(s) = v.coerce_str() {
            let split_result = self.collect_column_parts(separator, &s);
            if self.collapse_empty && split_result.is_empty() && self.column_names.is_empty() {
                return vec![Value::record(Record::new(), self.column_head)];
            }
            vec![self.record_from_column_parts(&split_result)]
        } else {
            vec![self.column_value_error(v)]
        }
    }

    fn collect_column_parts<'a>(&self, separator: &'a Regex, s: &'a str) -> Vec<&'a str> {
        separator
            .split(s)
            .filter(|x| !(self.collapse_empty && x.is_empty()))
            .collect()
    }

    fn generated_column_names(&self, count: usize) -> Vec<String> {
        if self.column_names.is_empty() {
            (0..count).map(|i| format!("column{}", i + 1)).collect()
        } else {
            self.column_names.clone()
        }
    }

    fn record_from_column_parts(&self, split_result: &[&str]) -> Value {
        let names = self.generated_column_names(split_result.len());
        let mut record = Record::new();
        if self.column_names.is_empty() {
            for (&part, name) in split_result.iter().zip(&names) {
                record.push(name, Value::string(part, self.column_head));
            }
        } else {
            for (&part, name) in split_result.iter().zip(&self.column_names) {
                record.push(name, Value::string(part, self.column_head));
            }
        }
        Value::record(record, self.column_head)
    }

